    "WALLY's father in PETALBURG CITY, after you beat NORMAN." to Tr(ja = "センリに かった あと トウカシティの ミツルの おとうさん。", fr = "Le père de TIMMY à CLEMENTI-VILLE, après votre victoire contre NORMAN.", de = "HEIKOs Vater in BLÜTENBURG CITY, nachdem du NORMAN besiegt hast.", it = "Il padre di LINO a PETALIPOLI, dopo che hai battuto NORMAN.", es = "El padre de BLASCO en CIUDAD PETALIA, tras vencer a NORMAN."),
    "HM04 STRENGTH" to Tr(ja = "ひでんマシン04 かいりき", fr = "CS04 FORCE", de = "VM04 STÄRKE", it = "MN04 FORZA", es = "MO04 FUERZA"),
    "The tunnel east of RUSTBORO CITY." to Tr(ja = "カナズミシティの ひがしの トンネル。", fr = "Le tunnel à l'est de MEROUVILLE.", de = "Der Tunnel östlich von METAROST CITY.", it = "Il tunnel a est di FERRUGIPOLI.", es = "El túnel al este de CIUDAD FÉRRICA."),
    "WANDA's boyfriend in RUSTURF TUNNEL, once you break the boulder there with ROCK SMASH." to Tr(ja = "カナシダトンネルの いわを いわくだきで こわした あと ミチルの こいびと。", fr = "Le petit ami de SYLVIE dans le TUNNEL MERAZON, une fois le rocher brisé avec ECLATE-ROC.", de = "HEIKEs Freund im METAFLURTUNNEL, wenn du dort den Felsen mit ZERTRÜMMERER zerschlägst.", it = "Il ragazzo di LINDA nel TUNNEL MENFERRO, dopo che hai rotto il masso con SPACCAROCCIA.", es = "El novio de CLARA en el TÚNEL FERVERGAL, cuando rompas la roca con GOLPE ROCA."),
    "HM05 FLASH" to Tr(ja = "ひでんマシン05 フラッシュ", fr = "CS05 FLASH", de = "VM05 BLITZ", it = "MN05 FLASH", es = "MO05 DESTELLO"),
    "A dark cave." to Tr(ja = "くらい どうくつ。", fr = "Une grotte sombre.", de = "Eine dunkle Höhle.", it = "Una grotta buia.", es = "Una cueva oscura."),
    "A hiker just inside GRANITE CAVE on DEWFORD's island." to Tr(ja = "ムロの しまに ある いしのどうくつの いりぐちの やまおとこ。", fr = "Un montagnard à l'entrée de la GROTTE GRANITE, sur l'île de MYOKARA.", de = "Ein Wanderer gleich am Eingang der GRANITHÖHLE auf der Insel von FAUSTAUHAVEN.", it = "Un montanaro appena dentro la GROTTA PIETROSA, sull'isola di BLURUVIA.", es = "Un montañero nada más entrar en la CUEVA GRANITO, en la isla de AZULIZA."),
    "HM06 ROCK SMASH" to Tr(ja = "ひでんマシン06 いわくだき", fr = "CS06 ECLATE-ROC", de = "VM06 ZERTRÜMMERER", it = "MN06 SPACCAROCCIA", es = "MO06 GOLPE ROCA"),
    "MAUVILLE CITY." to Tr(ja = "キンセツシティ。", fr = "LAVANDIA.", de = "MALVENFROH CITY.", it = "CICLAMIPOLI.", es = "CIUDAD MALVALONA."),
    "The ROCK SMASH GUY in a MAUVILLE CITY house." to Tr(ja = "キンセツシティの いえに いる いわくだきオヤジ。", fr = "Le TYPE ECLATE-ROC, dans une maison de LAVANDIA.", de = "Der ZERTRÜMMERER in einem Haus in MALVENFROH CITY.", it = "Il TIPO SPACCAROCCIA in una casa di CICLAMIPOLI.", es = "El MACHACARROCAS, en una casa de CIUDAD MALVALONA."),
    "HM07 WATERFALL" to Tr(ja = "ひでんマシン07 たきのぼり", fr = "CS07 CASCADE", de = "VM07 KASKADE", it = "MN07 CASCATA", es = "MO07 CASCADA"),
    "Late in the story, SOOTOPOLIS CITY." to Tr(ja = "ものがたりの おわりごろの ルネシティ。", fr = "Tard dans l'histoire, ATALANOPOLIS.", de = "Spät in der Geschichte, XENEROVILLE.", it = "Verso la fine della storia, CENERIDE.", es = "Al final de la historia, ARRECÍPOLIS."),
    "WALLACE in SOOTOPOLIS CITY, after the two ancient POKéMON are calmed." to Tr(ja = "2ひきの こだいの ポケモンが しずまった あと ルネシティの ミクリ。", fr = "MARC à ATALANOPOLIS, une fois les deux POKéMON antiques apaisés.", de = "WASSILI in XENEROVILLE, sobald die zwei uralten POKéMON beruhigt sind.", it = "ADRIANO a CENERIDE, dopo che i due POKéMON antichi si sono calmati.", es = "PLUBIO en ARRECÍPOLIS, cuando se calmen los dos POKéMON ancestrales."),
    "HM08 DIVE" to Tr(ja = "ひでんマシン08 ダイビング", fr = "CS08 PLONGEE", de = "VM08 TAUCHER", it = "MN08 SUB", es = "MO08 BUCEO"),
    "MOSSDEEP CITY." to Tr(ja = "トクサネシティ。", fr = "ALGATIA.", de = "MOOSBACH CITY.", it = "VERDEAZZUPOLI.", es = "CIUDAD ALGARIA."),
    "STEVEN at his house in MOSSDEEP CITY, after the SPACE CENTER." to Tr(ja = "うちゅうセンターの あと トクサネシティの いえに いる ダイゴ。", fr = "PIERRE chez lui à ALGATIA, après le CENTRE SPATIAL.", de = "TROY in seinem Haus in MOOSBACH CITY, nach dem RAUMFAHRTZENTRUM.", it = "ROCCO a casa sua a VERDEAZZUPOLI, dopo il CENTRO SPAZIALE.", es = "MÁXIMO en su casa de CIUDAD ALGARIA, tras el CENTRO ESPACIAL."),

    // WHERE IS: shops and services
    "SHOPS & SERVICES" to Tr(ja = "おみせと サービス", fr = "BOUTIQUES ET SERVICES", de = "LÄDEN & DIENSTE", it = "NEGOZI E SERVIZI", es = "TIENDAS Y SERVICIOS"),
    "Evolution stones" to Tr(ja = "しんかの いし", fr = "Pierres d'évolution", de = "Entwicklungssteine", it = "Pietre evolutive", es = "Piedras evolutivas"),
    "Diving treasure." to Tr(ja = "ダイビングで みつかる おたから。", fr = "Des trésors sous-marins.", de = "Schätze vom Meeresgrund.", it = "Tesori dei fondali.", es = "Tesoros del fondo marino."),
    "The TREASURE HUNTER's house on ROUTE 124 swaps shards found by DIVING: RED for a FIRE STONE, YELLOW for THUNDER, BLUE for WATER, GREEN for LEAF. Some lie around too: FIERY PATH (FIRE), ROUTE 119 (LEAF), NEW MAUVILLE (THUNDER), the ABANDONED SHIP (WATER), METEOR FALLS (MOON)." to Tr(ja = "124ばんすいどうの ハンターの こやで ダイビングで みつけた かけらを こうかん: あかいかけらは ほのおのいし、 きいろいかけらは かみなりのいし、 あおいかけらは みずのいし、 みどりのかけらは リーフのいし。 おちて いる ものも ある: ほのおのぬけみち (ほのお)、 119ばんどうろ (リーフ)、 ニューキンセツ (かみなり)、 すてられぶね (みず)、 りゅうせいのたき (つき)。", fr = "Le CHERCHEUR DE TRESORS du CHENAL 124 échange les TESSONS trouvés en PLONGEE : ROUGE contre une PIERRE FEU, JAUNE contre une PIERREFOUDRE, BLEU contre une PIERRE EAU, VERT contre une PIERREPLANTE. On en trouve aussi : CHEMIN ARDENT (FEU), ROUTE 119 (PLANTE), NEW LAVANDIA (FOUDRE), EPAVE (EAU), SITE METEORE (LUNE).", de = "Der SCHATZTAUCHER auf ROUTE 124 tauscht beim Tauchen gefundene STÜCKE: PURPUR gegen einen FEUERSTEIN, GELB gegen einen DONNERSTEIN, INDIGO gegen einen WASSERSTEIN, GRÜN gegen einen BLATTSTEIN. Manche liegen auch herum: FEURIGER PFAD (FEUER), ROUTE 119 (BLATT), NEU MALVENFROH (DONNER), SCHIFFSWRACK (WASSER), METEORFÄLLE (MOND).", it = "Il SUB CERCATESORI del PERCORSO 124 scambia i COCCI trovati con SUB: ROSSO per una PIETRAFOCAIA, GIALLO per una PIETRATUONO, BLU per una PIETRAIDRICA, VERDE per una PIETRAFOGLIA. Alcune sono in giro: CAMMINO ARDENTE (FOCAIA), PERCORSO 119 (FOGLIA), CICLANOVA (TUONO), VECCHIA NAVE (IDRICA), CASCATE METEORA (LUNARE).", es = "El BUSCATESOROS MARINOS de la RUTA 124 cambia las PARTES halladas con BUCEO: ROJA por una PIEDRA FUEGO, AMARILLA por una PIEDRATRUENO, AZUL por una PIEDRA AGUA, VERDE por una PIEDRA HOJA. Otras están por ahí: SENDA ÍGNEA (FUEGO), RUTA 119 (HOJA), MALVALANOVA (TRUENO), NAO ABANDONADA (AGUA), CASCADA METEORO (LUNAR)."),
    "MOVE DELETER" to Tr(ja = "わざわすれじいさん", fr = "EFFACEUR DE CAPACITES", de = "ATTACKEN-VERLERNER", it = "ELIMINAMOSSE", es = "QUITA-MOVIMIENTOS"),
    "A house in LILYCOVE CITY." to Tr(ja = "ミナモシティの いえ。", fr = "Une maison à NENUCRIQUE.", de = "Ein Haus in SEEGRASULB CITY.", it = "Una casa a PORTO ALGHEPOLI.", es = "Una casa en CIUDAD CALAGUA."),
    "MOVE TUTOR" to Tr(ja = "わざおしえマニア", fr = "MAITRE DES CAPACITES", de = "ATTACKEN-HELFER", it = "GUIDA MOSSE", es = "TUTOR de MOVIMIENTOS"),
    "A house in FALLARBOR TOWN. Bring a HEART SCALE." to Tr(ja = "ハジツゲタウンの いえ。 ハートのウロコを もって いこう。", fr = "Une maison à AUTEQUIA. Apportez une ECAILLECOEUR.", de = "Ein Haus in LAUBWECHSELFELD. Bring eine HERZSCHUPPE mit.", it = "Una casa a BRUNIFOGLIA. Porta una SQUAMA CUORE.", es = "Una casa en PUEBLO PARDAL. Lleva una ESCAMA CORAZÓN."),

    // WHERE IS: gift POKéMON
    "CASTFORM" to Tr(ja = "ポワルン", fr = "MORPHEO", de = "FORMEO", it = "CASTFORM", es = "CASTFORM"),
    "A research building." to Tr(ja = "けんきゅうしせつ。", fr = "Un centre de recherche.", de = "Ein Forschungsgebäude.", it = "Un edificio di ricerca.", es = "Un edificio de investigación."),
    "The WEATHER INSTITUTE on ROUTE 119 gives it to you after you drive TEAM AQUA out." to Tr(ja = "119ばんどうろの てんきけんきゅうじょで アクアだんを おいはらった あとに もらえる。", fr = "Le CENTRE METEO de la ROUTE 119 vous le donne une fois la TEAM AQUA chassée.", de = "Das KLIMA-INSTITUT auf ROUTE 119 gibt es dir, nachdem du TEAM AQUA vertrieben hast.", it = "L'ISTITUTO METEO del PERCORSO 119 te lo dà dopo che hai cacciato il TEAM IDRO.", es = "El INSTITUTO METEOROLÓGICO de la RUTA 119 te lo da tras echar al EQUIPO AQUA."),
    "WYNAUT (egg)" to Tr(ja = "ソーナノ (タマゴ)", fr = "OKEOKE (ŒUF)", de = "ISSO (EI)", it = "WYNAUT (UOVO)", es = "WYNAUT (HUEVO)"),
    "A hot-spring town." to Tr(ja = "おんせんの まち。", fr = "Un village thermal.", de = "Ein Ort mit heißen Quellen.", it = "Un paese termale.", es = "Un pueblo de aguas termales."),
    "An old woman in LAVARIDGE TOWN." to Tr(ja = "フエンタウンの おばあさん。", fr = "Une vieille dame à VERMILAVA.", de = "Eine alte Frau in BAD LAVASTADT.", it = "Un'anziana a CUORDILAVA.", es = "Una anciana en PUEBLO LAVACALDA."),
    "LILEEP / ANORITH" to Tr(ja = "リリーラ / アノプス", fr = "LILIA / ANORITH", de = "LILIEP / ANORITH", it = "LILEEP / ANORITH", es = "LILEEP / ANORITH"),
    "A tower in the desert." to Tr(ja = "さばくの とう。", fr = "Une tour dans le désert.", de = "Ein Turm in der Wüste.", it = "Una torre nel deserto.", es = "Una torre en el desierto."),
    "Pick the ROOT or CLAW FOSSIL at the top of the MIRAGE TOWER in the ROUTE 111 desert; DEVON CORP. 2F in RUSTBORO CITY revives it." to Tr(ja = "111ばんどうろの さばくに ある げんえいのとうの てっぺんで ねっこのカセキか ツメのカセキを えらぶ。 カナズミシティの デボンコーポレーション 2かいで ふっかつ して もらえる。", fr = "Prenez le FOSS. RACINE ou le FOSS. GRIFFE au sommet de la TOUR MIRAGE, dans le désert de la ROUTE 111 ; le 1er étage de DEVON à MEROUVILLE le ranime.", de = "Nimm oben im WUNDERTURM in der Wüste auf ROUTE 111 das WURZELFOSSIL oder das KLAUENFOSSIL; im 1. Stock der DEVON CORPORATION in METAROST CITY wird es wiederbelebt.", it = "Prendi il RADIFOSSILE o il FOSSILUNGHIA in cima alla TORRE MIRAGGIO, nel deserto del PERCORSO 111; al 1º piano della DEVON SpA a FERRUGIPOLI lo rianimano.", es = "Coge el FÓSIL RAÍZ o el FÓSIL GARRA en lo alto de la TORRE ESPEJISMO, en el desierto de la RUTA 111; en la planta 1 de DEVON S.A., en CIUDAD FÉRRICA, lo reviven."),
    "BELDUM" to Tr(ja = "ダンバル", fr = "TERHAL", de = "TANHEL", it = "BELDUM", es = "BELDUM"),
    "Post-game." to Tr(ja = "エンディングの あと。", fr = "Après l'aventure principale.", de = "Nach dem Abspann.", it = "Dopo i titoli di coda.", es = "Tras terminar la historia."),
    "STEVEN's house in MOSSDEEP CITY, after the HALL OF FAME." to Tr(ja = "でんどういりの あと トクサネシティの ダイゴの いえ。", fr = "La maison de PIERRE à ALGATIA, après le PANTHEON DES DRESSEURS.", de = "TROYS Haus in MOOSBACH CITY, nach der RUHMESHALLE.", it = "La casa di ROCCO a VERDEAZZUPOLI, dopo la SALA d'ONORE.", es = "La casa de MÁXIMO en CIUDAD ALGARIA, tras el HALL de la FAMA."),
    "CHIKORITA / CYNDAQUIL / TOTODILE" to Tr(ja = "チコリータ / ヒノアラシ / ワニノコ", fr = "GERMIGNON / HERICENDRE / KAIMINUS", de = "ENDIVIE / FEURIGEL / KARNIMANI", it = "CHIKORITA / CYNDAQUIL / TOTODILE", es = "CHIKORITA / CYNDAQUIL / TOTODILE"),
    "Post-game, and a full HOENN DEX." to Tr(ja = "エンディングの あと。 ホウエンずかんを かんせい させて。", fr = "Après l'aventure, avec le POKéDEX de HOENN complet.", de = "Nach dem Abspann, mit vollem HOENN-POKéDEX.", it = "Dopo i titoli di coda, con il POKéDEX di HOENN completo.", es = "Tras la historia, con la POKéDEX de HOENN completa."),
    "After the HALL OF FAME, catch every HOENN POKéMON (not JIRACHI or DEOXYS); PROF. BIRCH then lets you pick one." to Tr(ja = "でんどういりの あと ホウエンの ポケモンを ぜんぶ つかまえる (ジラーチと デオキシスは のぞく)。 すると オダマキはかせが 1ぴき えらばせて くれる。", fr = "Après le PANTHEON DES DRESSEURS, attrapez tous les POKéMON de HOENN (sauf JIRACHI et DEOXYS) ; le PROF. SEKO vous laisse alors en choisir un.", de = "Fang nach der RUHMESHALLE alle POKéMON aus HOENN (außer JIRACHI und DEOXYS); dann lässt PROF. BIRK dich eines wählen.", it = "Dopo la SALA d'ONORE, cattura tutti i POKéMON di HOENN (tranne JIRACHI e DEOXYS); poi il PROF. BIRCH te ne fa scegliere uno.", es = "Tras el HALL de la FAMA, atrapa todos los POKéMON de HOENN (salvo JIRACHI y DEOXYS); luego el PROF. ABEDUL te deja elegir uno."),

    // WHERE IS: legendary POKéMON
    "LEGENDARY POKéMON" to Tr(ja = "でんせつの ポケモン", fr = "POKéMON LEGENDAIRES", de = "LEGENDÄRE POKéMON", it = "POKéMON LEGGENDARI", es = "POKéMON LEGENDARIOS"),
    "RAYQUAZA" to Tr(ja = "レックウザ", fr = "RAYQUAZA", de = "RAYQUAZA", it = "RAYQUAZA", es = "RAYQUAZA"),
    "A tower in the sea near PACIFIDLOG TOWN." to Tr(ja = "キナギタウンの ちかくの うみに たつ とう。", fr = "Une tour en mer près de PACIFIVILLE.", de = "Ein Turm im Meer bei FLOSSBRUNN.", it = "Una torre in mare vicino a OROCEA.", es = "Una torre en el mar cerca de PUEBLO OROMAR."),
    "The top of the SKY PILLAR on ROUTE 131, once the story's SOOTOPOLIS CITY crisis is over. Some floors crack: ride the MACH BIKE across them." to Tr(ja = "ルネシティの じけんが おわった あと 131ばんすいどうの そらのはしらの てっぺん。 ひびの はいった ゆかは マッハじてんしゃで わたろう。", fr = "Au sommet du PILIER CELESTE (CHENAL 131), une fois la crise d'ATALANOPOLIS terminée. Certains sols se fissurent : traversez-les en VELO COURSE.", de = "Ganz oben im HIMMELTURM auf ROUTE 131, wenn die Krise in XENEROVILLE vorbei ist. Manche Böden brechen: Fahr mit dem EILRAD darüber.", it = "In cima alla TORRE dei CIELI sul PERCORSO 131, finita la crisi di CENERIDE. Alcuni pavimenti si crepano: attraversali con la BICI CORSA.", es = "En lo alto del PILAR CELESTE, en la RUTA 131, cuando acabe la crisis de ARRECÍPOLIS. Algunos suelos se agrietan: crúzalos con la BICI CARRERA."),
    "GROUDON / KYOGRE" to Tr(ja = "グラードン / カイオーガ", fr = "GROUDON / KYOGRE", de = "GROUDON / KYOGRE", it = "GROUDON / KYOGRE", es = "GROUDON / KYOGRE"),
    "Post-game - watch the weather reports." to Tr(ja = "エンディングの あと。 てんきよほうに ちゅうもく。", fr = "Après l'aventure : suivez la météo.", de = "Nach dem Abspann - achte auf den Wetterbericht.", it = "Dopo i titoli di coda: segui il meteo.", es = "Tras la historia: atento al parte meteorológico."),
    "After the HALL OF FAME, a scientist at the WEATHER INSTITUTE reports a drought or heavy rain on some route. A drought leads to TERRA CAVE (GROUDON), heavy rain to MARINE CAVE underwater (KYOGRE, use DIVE)." to Tr(ja = "でんどういりの あと てんきけんきゅうじょの けんきゅういんが どこかの どうろの ひでりや おおあめを おしえて くれる。 ひでりなら りくのどうくつ (グラードン)、 おおあめなら うみの なかの うみのどうくつ (カイオーガ、 ダイビングを つかう)。", fr = "Après le PANTHEON DES DRESSEURS, un chercheur du CENTRE METEO signale une sécheresse ou de fortes pluies sur une route. La sécheresse mène à la GROTTE TERRA (GROUDON), les pluies à la GROTTE MARINE sous l'eau (KYOGRE, avec PLONGEE).", de = "Nach der RUHMESHALLE meldet ein Forscher im KLIMA-INSTITUT eine Dürre oder Starkregen auf einer Route. Dürre führt zur TERRAHÖHLE (GROUDON), Starkregen zur OZEANHÖHLE unter Wasser (KYOGRE, mit TAUCHER).", it = "Dopo la SALA d'ONORE, uno scienziato dell'ISTITUTO METEO segnala siccità o piogge forti su un percorso. La siccità porta alla GROTTA TERRA (GROUDON), la pioggia alla GROTTA MARE sott'acqua (KYOGRE, usa SUB).", es = "Tras el HALL de la FAMA, un científico del INSTITUTO METEOROLÓGICO avisa de sequía o lluvias fuertes en alguna ruta. La sequía lleva a la CUEVA TERRENA (GROUDON); las lluvias, a la CUEVA MARINA bajo el agua (KYOGRE, usa BUCEO)."),
    "REGIROCK / REGICE / REGISTEEL" to Tr(ja = "レジロック / レジアイス / レジスチル", fr = "REGIROCK / REGICE / REGISTEEL", de = "REGIROCK / REGICE / REGISTEEL", it = "REGIROCK / REGICE / REGISTEEL", es = "REGIROCK / REGICE / REGISTEEL"),
    "It starts under the sea, with two particular POKéMON." to Tr(ja = "うみの そこで はじまる。 とくべつな 2ひきの ポケモンが ひつよう。", fr = "Ça commence sous la mer, avec deux POKéMON précis.", de = "Es beginnt unter dem Meer, mit zwei bestimmten POKéMON.", it = "Inizia sotto il mare, con due POKéMON precisi.", es = "Empieza bajo el mar, con dos POKéMON concretos."),
    "First open the doors: put WAILORD first and RELICANTH last in your party and read the braille in the SEALED CHAMBER (DIVE on ROUTE 134). Then, after reading each ruin's braille: DESERT RUINS (ROUTE 111) - use ROCK SMASH; ANCIENT TOMB (ROUTE 120) - use FLASH; ISLAND CAVE (ROUTE 105) - walk one full lap along the walls." to Tr(ja = "まず とびらを ひらく: てもちの せんとうに ホエルオー、 さいごに ジーランスを いれて おふれのせきしつ (134ばんすいどうで ダイビング) の てんじを よむ。 つぎに それぞれの いせきの てんじを よんだ あと: さばくいせき (111ばんどうろ) は いわくだき、 こだいづか (120ばんどうろ) は フラッシュ、 こじまのよこあな (105ばんすいどう) は かべに そって 1しゅう あるく。", fr = "Ouvrez d'abord les portes : WAILORD en tête et RELICANTH en dernier dans l'équipe, lisez le braille du SANCTUAIRE (PLONGEE au CHENAL 134). Puis, après avoir lu le braille de chaque ruine : RUINES DESERT (ROUTE 111), utilisez ECLATE-ROC ; TOMBEAU ANTIQUE (ROUTE 120), FLASH ; GROTTE ISLAND (CHENAL 105), faites un tour complet le long des murs.", de = "Öffne zuerst die Türen: WAILORD an erster und RELICANTH an letzter Stelle im Team, dann lies die Blindenschrift in der SIEGELKAMMER (TAUCHER auf ROUTE 134). Danach, nachdem du jeweils die Blindenschrift gelesen hast: WÜSTENRUINE (ROUTE 111) - setz ZERTRÜMMERER ein; GRABMAL (ROUTE 120) - BLITZ; INSELHÖHLE (ROUTE 105) - lauf einmal ganz an den Wänden entlang.", it = "Prima apri le porte: WAILORD primo e RELICANTH ultimo in squadra, poi leggi il Braille nella SALA INCISA (SUB sul PERCORSO 134). Poi, dopo aver letto il Braille di ogni rovina: ROVINE SABBIOSE (PERCORSO 111) - usa SPACCAROCCIA; TOMBA ANTICA (PERCORSO 120) - FLASH; GROTTA INSULARE (PERCORSO 105) - fai un giro completo lungo le pareti.", es = "Primero abre las puertas: WAILORD el primero y RELICANTH el último del equipo, y lee el braille de la CÁMARA SELLADA (BUCEO en la RUTA 134). Después, tras leer el braille de cada ruina: RUINAS DESIERTO (RUTA 111), usa GOLPE ROCA; TUMBA ANTIGUA (RUTA 120), DESTELLO; CUEVA INSULAR (RUTA 105), da una vuelta entera junto a las paredes."),
    "LATIAS / LATIOS" to Tr(ja = "ラティアス / ラティオス", fr = "LATIAS / LATIOS", de = "LATIAS / LATIOS", it = "LATIAS / LATIOS", es = "LATIAS / LATIOS"),
    "Post-game, at home." to Tr(ja = "エンディングの あと、 いえで。", fr = "Après l'aventure, à la maison.", de = "Nach dem Abspann, zu Hause.", it = "Dopo i titoli di coda, a casa.", es = "Tras la historia, en casa."),
    "After the HALL OF FAME, go home: a TV news flash asks the colour. RED makes LATIAS roam HOENN, BLUE makes LATIOS." to Tr(ja = "でんどういりの あと いえに かえると テレビの ニュースで いろを きかれる。 あかなら ラティアス、 あおなら ラティオスが ホウエンを かけまわる。", fr = "Après le PANTHEON DES DRESSEURS, rentrez chez vous : un flash info à la télé demande une couleur. ROUGE fait errer LATIAS dans HOENN, BLEU LATIOS.", de = "Geh nach der RUHMESHALLE nach Hause: Eine Eilmeldung im Fernsehen fragt nach der Farbe. Bei ROT streift LATIAS durch HOENN, bei BLAU LATIOS.", it = "Dopo la SALA d'ONORE, torna a casa: un notiziario in TV chiede il colore. ROSSO fa vagare LATIAS per HOENN, BLU LATIOS.", es = "Tras el HALL de la FAMA, vuelve a casa: un avance informativo en la tele pregunta el color. ROJO hace que LATIAS vague por HOENN; AZUL, LATIOS."),
    "KECLEON" to Tr(ja = "カクレオン", fr = "KECLEON", de = "KECLEON", it = "KECLEON", es = "KECLEON"),
    "You can't see it." to Tr(ja = "すがたが みえない。", fr = "Il est invisible.", de = "Man sieht es nicht.", it = "Non si vede.", es = "No se ve."),
    "Invisible ones sit on ROUTES 119 and 120 and in FORTREE CITY. The DEVON SCOPE reveals them." to Tr(ja = "119ばんどうろと 120ばんどうろ、 ヒワマキシティに みえない カクレオンが いる。 デボンスコープで すがたが みえる。", fr = "Des KECLEON invisibles se cachent sur les ROUTES 119 et 120 et à CIMETRONELLE. Le DEVON SCOPE les révèle.", de = "Unsichtbare sitzen auf ROUTE 119 und 120 und in BAUMHAUSEN CITY. Der DEVON-SCOPE macht sie sichtbar.", it = "Ce ne sono di invisibili sui PERCORSI 119 e 120 e a FORESTOPOLI. Il DEVONSCOPIO li rivela.", es = "Hay algunos invisibles en las RUTAS 119 y 120 y en CIUDAD ARBORADA. El DETECTOR DEVON los revela."),

    // STUCK?
    "EARLY GAME" to Tr(ja = "はじめの ほう", fr = "DÉBUT DU JEU", de = "SPIELBEGINN", it = "INIZIO", es = "PRINCIPIO"),
    "How do I get to DEWFORD TOWN?" to Tr(ja = "ムロタウンへの いきかたは?", fr = "Comment aller au VILLAGE MYOKARA ?", de = "Wie komme ich nach FAUSTAUHAVEN?", it = "Come arrivo a BLURUVIA?", es = "¿Cómo llego a PUEBLO AZULIZA?"),
    "An old sailor lost his pet." to Tr(ja = "ふるい ふなのりが ペットを なくした。", fr = "Un vieux marin a perdu son compagnon.", de = "Ein alter Seebär hat sein Haustier verloren.", it = "Un vecchio marinaio ha perso il suo animale.", es = "Un viejo marinero ha perdido a su mascota."),
    "MR. BRINEY sails you from his cottage on ROUTE 104 once you've rescued his PEEKO from TEAM AQUA in RUSTURF TUNNEL." to Tr(ja = "カナシダトンネルで アクアだんから ピーコちゃんを たすけると 104ばんどうろの こやから ハギろうじんが ふねで つれて いって くれる。", fr = "M. MARCO vous emmène en bateau depuis son cottage de la ROUTE 104 une fois son PIKO sauvé de la TEAM AQUA dans le TUNNEL MERAZON.", de = "MR. BRACK bringt dich von seiner Hütte auf ROUTE 104 mit dem Boot hin, sobald du sein PECKO im METAFLURTUNNEL vor TEAM AQUA gerettet hast.", it = "Il SIG. MARINO ti porta in barca dal suo cottage sul PERCORSO 104 dopo che hai salvato il suo PEEKO dal TEAM IDRO nel TUNNEL MENFERRO.", es = "El SR. ARENQUE te lleva en barco desde su casa de la RUTA 104 cuando rescatas a su PEEKO del EQUIPO AQUA en el TÚNEL FERVERGAL."),
    "Where are the stolen DEVON GOODS?" to Tr(ja = "ぬすまれた デボンのにもつは どこ?", fr = "Où est le PACK DEVON volé ?", de = "Wo sind die gestohlenen DEVON-WAREN?", it = "Dov'è la MERCE DEVON rubata?", es = "¿Dónde están las PIEZAS DEVON robadas?"),
    "Follow the thief east." to Tr(ja = "どろぼうを おって ひがしへ。", fr = "Suivez le voleur vers l'est.", de = "Folge dem Dieb nach Osten.", it = "Segui il ladro verso est.", es = "Sigue al ladrón hacia el este."),
    "A TEAM AQUA grunt fled into RUSTURF TUNNEL, east of RUSTBORO CITY. Beat him there." to Tr(ja = "アクアだんの したっぱが カナズミシティの ひがしの カナシダトンネルに にげこんだ。 そこで たおそう。", fr = "Un SBIRE de la TEAM AQUA s'est enfui dans le TUNNEL MERAZON, à l'est de MEROUVILLE. Battez-le là-bas.", de = "Ein RÜPEL von TEAM AQUA ist in den METAFLURTUNNEL östlich von METAROST CITY geflohen. Besiege ihn dort.", it = "Una RECLUTA del TEAM IDRO è fuggita nel TUNNEL MENFERRO, a est di FERRUGIPOLI. Battila lì.", es = "Un SOLDADO del EQUIPO AQUA huyó al TÚNEL FERVERGAL, al este de CIUDAD FÉRRICA. Derrótalo allí."),
    "PETALBURG CITY's gym won't let me in" to Tr(ja = "トウカシティの ジムに はいれない", fr = "L'ARENE de CLEMENTI-VILLE me refuse l'entrée", de = "Die ARENA in BLÜTENBURG CITY lässt mich nicht rein", it = "La PALESTRA di PETALIPOLI non mi fa entrare", es = "No me dejan entrar al GIMNASIO de CIUDAD PETALIA"),
    "Come back with more badges." to Tr(ja = "もっと バッジを あつめて から。", fr = "Revenez avec plus de badges.", de = "Komm mit mehr Orden wieder.", it = "Torna con più medaglie.", es = "Vuelve con más medallas."),
    "Your father NORMAN battles you once you have four badges." to Tr(ja = "バッジが 4こ あれば おとうさんの センリが たたかって くれる。", fr = "Votre père NORMAN vous affronte dès que vous avez quatre badges.", de = "Dein Vater NORMAN kämpft gegen dich, sobald du vier Orden hast.", it = "Tuo padre NORMAN ti sfida quando hai quattro medaglie.", es = "Tu padre NORMAN lucha contigo cuando tengas cuatro medallas."),
    "MID GAME" to Tr(ja = "なかごろ", fr = "MILIEU DU JEU", de = "SPIELMITTE", it = "METÀ GIOCO", es = "MITAD"),
    "TEAM MAGMA blocks the cable car on ROUTE 112" to Tr(ja = "112ばんどうろの ロープウェイを マグマだんが ふさいで いる", fr = "La TEAM MAGMA bloque le TELEPHERIQUE de la ROUTE 112", de = "TEAM MAGMA versperrt die SEILBAHN auf ROUTE 112", it = "Il TEAM MAGMA blocca la FUNIVIA sul PERCORSO 112", es = "El EQUIPO MAGMA bloquea el TELEFÉRICO de la RUTA 112"),
    "Go around the mountain." to Tr(ja = "やまを まわりこもう。", fr = "Faites le tour de la montagne.", de = "Geh um den Berg herum.", it = "Fai il giro della montagna.", es = "Rodea la montaña."),
    "They leave after the scene at METEOR FALLS - go north from MAUVILLE CITY on ROUTE 111, then west on ROUTE 113 to FALLARBOR TOWN and ROUTE 114." to Tr(ja = "りゅうせいのたきの できごとの あとで いなくなる。 キンセツシティから 111ばんどうろを きたへ、 113ばんどうろを にしへ すすみ ハジツゲタウンと 114ばんどうろへ。", fr = "Ils partent après la scène du SITE METEORE : allez au nord de LAVANDIA par la ROUTE 111, puis à l'ouest par la ROUTE 113 vers AUTEQUIA et la ROUTE 114.", de = "Sie ziehen nach der Szene bei den METEORFÄLLEN ab - geh von MALVENFROH CITY über ROUTE 111 nach Norden, dann über ROUTE 113 nach Westen nach LAUBWECHSELFELD und zu ROUTE 114.", it = "Se ne vanno dopo la scena alle CASCATE METEORA: da CICLAMIPOLI vai a nord sul PERCORSO 111, poi a ovest sul PERCORSO 113 fino a BRUNIFOGLIA e al PERCORSO 114.", es = "Se van tras la escena de la CASCADA METEORO: desde CIUDAD MALVALONA ve al norte por la RUTA 111 y luego al oeste por la RUTA 113 hasta PUEBLO PARDAL y la RUTA 114."),
    "A sandstorm keeps pushing me back on ROUTE 111" to Tr(ja = "111ばんどうろで すなあらしに おしもどされる", fr = "Une tempête de sable me repousse sur la ROUTE 111", de = "Ein Sandsturm drängt mich auf ROUTE 111 zurück", it = "Una tempesta di sabbia mi respinge sul PERCORSO 111", es = "Una tormenta de arena me hace retroceder en la RUTA 111"),
    "Protect your eyes." to Tr(ja = "めを まもろう。", fr = "Protégez vos yeux.", de = "Schütze deine Augen.", it = "Proteggi gli occhi.", es = "Protégete los ojos."),
    "You need the GO-GOGGLES, from your rival in LAVARIDGE TOWN after the fourth badge." to Tr(ja = "4つめの バッジの あと フエンタウンで ライバルに もらえる ゴーゴーゴーグルが ひつよう。", fr = "Il vous faut les LUNET. SABLE, que votre rival donne à VERMILAVA après le quatrième badge.", de = "Du brauchst das WÜSTENGLAS, das dir dein Rivale nach dem vierten Orden in BAD LAVASTADT gibt.", it = "Ti servono gli OCCHIALONI, che il tuo rivale ti dà a CUORDILAVA dopo la quarta medaglia.", es = "Necesitas las GAFAS AISLANTES, que te da tu rival en PUEBLO LAVACALDA tras la cuarta medalla."),
    "Something invisible blocks FORTREE CITY's gym" to Tr(ja = "ヒワマキシティの ジムの まえを みえない なにかが ふさいで いる", fr = "Quelque chose d'invisible bloque l'ARENE de CIMETRONELLE", de = "Etwas Unsichtbares versperrt die ARENA in BAUMHAUSEN CITY", it = "Qualcosa di invisibile blocca la PALESTRA di FORESTOPOLI", es = "Algo invisible bloquea el GIMNASIO de CIUDAD ARBORADA"),
    "Look east of FORTREE CITY." to Tr(ja = "ヒワマキシティの ひがしを さがそう。", fr = "Cherchez à l'est de CIMETRONELLE.", de = "Sieh dich östlich von BAUMHAUSEN CITY um.", it = "Cerca a est di FORESTOPOLI.", es = "Busca al este de CIUDAD ARBORADA."),
    "It's a KECLEON. Get the DEVON SCOPE from STEVEN on ROUTE 120, then use it on the blocked spot." to Tr(ja = "カクレオンだ。 120ばんどうろで ダイゴから デボンスコープを もらい ふさがれた ばしょで つかおう。", fr = "C'est un KECLEON. Obtenez le DEVON SCOPE auprès de PIERRE sur la ROUTE 120, puis utilisez-le devant l'obstacle.", de = "Es ist ein KECLEON. Hol dir den DEVON-SCOPE von TROY auf ROUTE 120 und setz ihn an der versperrten Stelle ein.", it = "È un KECLEON. Prendi il DEVONSCOPIO da ROCCO sul PERCORSO 120 e usalo nel punto bloccato.", es = "Es un KECLEON. Consigue el DETECTOR DEVON de MÁXIMO en la RUTA 120 y úsalo en el sitio bloqueado."),
    "LATE GAME" to Tr(ja = "おわりの ほう", fr = "FIN DU JEU", de = "SPIELENDE", it = "FINALE", es = "FINAL"),
    "How do I get into SOOTOPOLIS CITY?" to Tr(ja = "ルネシティへの はいりかたは?", fr = "Comment entrer à ATALANOPOLIS ?", de = "Wie komme ich nach XENEROVILLE?", it = "Come entro a CENERIDE?", es = "¿Cómo entro en ARRECÍPOLIS?"),
    "From below." to Tr(ja = "したから。", fr = "Par en dessous.", de = "Von unten.", it = "Da sotto.", es = "Desde abajo."),
    "It sits inside a crater: DIVE down on ROUTE 126 and surface inside." to Tr(ja = "クレーターの なかに ある。 126ばんすいどうで ダイビングで もぐり なかで うきあがろう。", fr = "Elle est dans un cratère : utilisez PLONGEE au CHENAL 126 et remontez à l'intérieur.", de = "Es liegt in einem Krater: Tauch auf ROUTE 126 mit TAUCHER ab und drinnen wieder auf.", it = "Si trova in un cratere: usa SUB sul PERCORSO 126 e riemergi all'interno.", es = "Está dentro de un cráter: usa BUCEO en la RUTA 126 y sal a la superficie dentro."),
    "SOOTOPOLIS CITY's gym is closed" to Tr(ja = "ルネシティの ジムが しまって いる", fr = "L'ARENE d'ATALANOPOLIS est fermée", de = "Die ARENA in XENEROVILLE ist geschlossen", it = "La PALESTRA di CENERIDE è chiusa", es = "El GIMNASIO de ARRECÍPOLIS está cerrado"),
    "Someone in SOOTOPOLIS CITY knows what to do." to Tr(ja = "ルネシティの だれかが しって いる。", fr = "Quelqu'un à ATALANOPOLIS sait quoi faire.", de = "Jemand in XENEROVILLE weiß, was zu tun ist.", it = "Qualcuno a CENERIDE sa cosa fare.", es = "Alguien en ARRECÍPOLIS sabe qué hacer."),
    "Calm the two ancient POKéMON first: WALLACE sends you to the SKY PILLAR on ROUTE 131." to Tr(ja = "まず 2ひきの こだいの ポケモンを しずめよう。 ミクリが 131ばんすいどうの そらのはしらへ いかせて くれる。", fr = "Apaisez d'abord les deux POKéMON antiques : MARC vous envoie au PILIER CELESTE (CHENAL 131).", de = "Beruhige zuerst die zwei uralten POKéMON: WASSILI schickt dich zum HIMMELTURM auf ROUTE 131.", it = "Prima calma i due POKéMON antichi: ADRIANO ti manda alla TORRE dei CIELI sul PERCORSO 131.", es = "Primero calma a los dos POKéMON ancestrales: PLUBIO te envía al PILAR CELESTE de la RUTA 131."),
    "How do I reach EVER GRANDE CITY?" to Tr(ja = "サイユウシティへの いきかたは?", fr = "Comment aller à ETERNARA ?", de = "Wie erreiche ich PRACHTPOLIS CITY?", it = "Come raggiungo IRIDOPOLI?", es = "¿Cómo llego a CIUDAD COLOSALIA?"),
    "Go up." to Tr(ja = "うえへ。", fr = "Montez.", de = "Nach oben.", it = "Sali.", es = "Sube."),
    "It's up a waterfall: you need HM07 WATERFALL (from WALLACE) and the RAIN BADGE." to Tr(ja = "たきの うえに ある。 ひでんマシン07 たきのぼり (ミクリから) と レインバッジが ひつよう。", fr = "Elle est en haut d'une cascade : il faut la CS07 CASCADE (de MARC) et le BADGE PLUIE.", de = "Es liegt oberhalb eines Wasserfalls: Du brauchst VM07 KASKADE (von WASSILI) und den SCHAUERORDEN.", it = "È in cima a una cascata: servono la MN07 CASCATA (da ADRIANO) e la MEDAGLIA PIOGGIA.", es = "Está en lo alto de una cascada: necesitas la MO07 CASCADA (de PLUBIO) y la MEDALLA LLUVIA."),

    // NEXT BOSS: the trainers' own class and name (each ROM's gTrainers / class table).
    "LEADER ROXANNE" to Tr(ja = "ジムリーダー ツツジ", fr = "CHAMPION ROXANNE", de = "ARENALEITERIN FELIZIA", it = "CAPOPALESTRA PETRA", es = "LÍDER PETRA"),
    "RUSTBORO CITY GYM" to Tr(ja = "カナズミジム", fr = "ARENE DE MEROUVILLE", de = "ARENA VON METAROST CITY", it = "PALESTRA DI FERRUGIPOLI", es = "GIMNASIO DE CIUDAD FÉRRICA"),
    "LEADER BRAWLY" to Tr(ja = "ジムリーダー トウキ", fr = "CHAMPION BASTIEN", de = "ARENALEITER KAMILLO", it = "CAPOPALESTRA RUDI", es = "LÍDER MARCIAL"),
    "DEWFORD TOWN GYM" to Tr(ja = "ムロジム", fr = "ARENE DU VILLAGE MYOKARA", de = "ARENA VON FAUSTAUHAVEN", it = "PALESTRA DI BLURUVIA", es = "GIMNASIO DE PUEBLO AZULIZA"),
    "LEADER WATTSON" to Tr(ja = "ジムリーダー テッセン", fr = "CHAMPION VOLTERE", de = "ARENALEITER WALTER", it = "CAPOPALESTRA WALTER", es = "LÍDER ERICO"),
    "MAUVILLE CITY GYM" to Tr(ja = "キンセツジム", fr = "ARENE DE LAVANDIA", de = "ARENA VON MALVENFROH CITY", it = "PALESTRA DI CICLAMIPOLI", es = "GIMNASIO DE CIUDAD MALVALONA"),
    "LEADER FLANNERY" to Tr(ja = "ジムリーダー アスナ", fr = "CHAMPION ADRIANE", de = "ARENALEITERIN FLAVIA", it = "CAPOPALESTRA FIAMMETTA", es = "LÍDER CANDELA"),
    "LAVARIDGE TOWN GYM" to Tr(ja = "フエンジム", fr = "ARENE DE VERMILAVA", de = "ARENA VON BAD LAVASTADT", it = "PALESTRA DI CUORDILAVA", es = "GIMNASIO DE PUEBLO LAVACALDA"),
    "LEADER NORMAN" to Tr(ja = "ジムリーダー センリ", fr = "CHAMPION NORMAN", de = "ARENALEITER NORMAN", it = "CAPOPALESTRA NORMAN", es = "LÍDER NORMAN"),
    "PETALBURG CITY GYM" to Tr(ja = "トウカジム", fr = "ARENE DE CLEMENTI-VILLE", de = "ARENA VON BLÜTENBURG CITY", it = "PALESTRA DI PETALIPOLI", es = "GIMNASIO DE CIUDAD PETALIA"),
    "LEADER WINONA" to Tr(ja = "ジムリーダー ナギ", fr = "CHAMPION ALIZEE", de = "ARENALEITERIN WIBKE", it = "CAPOPALESTRA ALICE", es = "LÍDER ALANA"),
    "FORTREE CITY GYM" to Tr(ja = "ヒワマキジム", fr = "ARENE DE CIMETRONELLE", de = "ARENA VON BAUMHAUSEN CITY", it = "PALESTRA DI FORESTOPOLI", es = "GIMNASIO DE CIUDAD ARBORADA"),
